INSERT OR REPLACE INTO documents (id, root_id, type_id, type_version, version_of_id, version_number, is_current_draft, is_published, status, parent_root_id, slug, path, title, zone, sort_order, visible, published_at, scheduled_at, expires_at, deleted_at, tenant_id, locale, translation_group_id, data, metadata, owner_id, created_by, updated_by, created_at, updated_at) VALUES ('job-react-dev', 'job-react-dev', 'jobs', 1, NULL, 1, 1, 1, 'published', '', 'react-frontend-developer-full-time', NULL, 'React Frontend Developer (Full-time)', NULL, 0, 1, 1782331377739, NULL, NULL, NULL, 'default', 'default', '', '{"title_ar":"مطور واجهات أمامية React (دوام كامل)","title_en":"React Frontend Developer (Full-time)","slug":"react-frontend-developer-full-time","description_ar":"نبحث عن مطور React ذو خبرة للانضمام إلى فريقنا البرمجي في شيشلي. المهام تشمل بناء واجهات الويب التفاعلية وتحسين أداء المواقع. المتطلبات: خبرة سنتين على الأقل في React/Next.js وإجادة اللغة الإنجليزية.","description_en":"We are looking for an experienced React Developer to join our engineering team in Şişli. Responsibilities include building responsive UI components and web performance tuning. Requirements: 2+ years of experience with React/Next.js and proficiency in English.","company":"comp-ist-tech","category":"cat-it","location_ar":"شيشلي، إسطنبول","location_en":"Sisli, Istanbul","jobType":"full-time","salary":"35,000 - 48,000 TL","applyLink":"https://istanbultechhub.example.com/apply","applyEmail":"careers@istanbultechhub.example.com","language":"en","featured":true,"publishedAt":1782331377739,"status":"published"}', '{}', NULL, NULL, NULL, 1782331377739, 1782331377739);
INSERT OR REPLACE INTO documents (id, root_id, type_id, type_version, version_of_id, version_number, is_current_draft, is_published, status, parent_root_id, slug, path, title, zone, sort_order, visible, published_at, scheduled_at, expires_at, deleted_at, tenant_id, locale, translation_group_id, data, metadata, owner_id, created_by, updated_by, created_at, updated_at) VALUES ('job-sales-agent', 'job-sales-agent', 'jobs', 1, NULL, 1, 1, 1, 'published', '', 'bilingual-real-estate-consultant', NULL, 'Bilingual Real Estate Consultant', NULL, 0, 1, 1782331377739, NULL, NULL, NULL, 'default', 'default', '', '{"title_ar":"مستشار عقاري ناطق بالعربية والانجليزية","title_en":"Bilingual Real Estate Consultant","slug":"bilingual-real-estate-consultant","description_ar":"مطلوب مستشار مبيعات عقارية للعمل في مكتبنا الرئيسي في الفاتح. يتطلب العمل التواصل مع العملاء العرب والأجانب المهتمين بالاستثمار العقاري في تركيا. يفضل توفر رخصة قيادة وخبرة في مبيعات المجمعات السكنية.","description_en":"We are seeking a Real Estate Consultant for our Fatih office. The role involves negotiating and coordinating transactions with Arab and international buyers investing in Turkey. Drivers license and real estate sales experience in Istanbul are highly preferred.","company":"comp-bosporus-re","category":"cat-realestate","location_ar":"الفاتح، إسطنبول","location_en":"Fatih, Istanbul","jobType":"full-time","salary":"25,000 TL + عمولات مجزية","applyLink":"","applyEmail":"sales@bosporusre.example.com","language":"both","featured":true,"publishedAt":1782331377739,"status":"published"}', '{}', NULL, NULL, NULL, 1782331377739, 1782331377739);
INSERT OR REPLACE INTO documents (id, root_id, type_id, type_version, version_of_id, version_number, is_current_draft, is_published, status, parent_root_id, slug, path, title, zone, sort_order, visible, published_at, scheduled_at, expires_at, deleted_at, tenant_id, locale, translation_group_id, data, metadata, owner_id, created_by, updated_by, created_at, updated_at) VALUES ('job-receptionist', 'job-receptionist', 'jobs', 1, NULL, 1, 1, 1, 'published', '', 'hotel-receptionist-night-shift', NULL, 'Hotel Receptionist (Night Shift)', NULL, 0, 1, 1782331377739, NULL, NULL, NULL, 'default', 'default', '', '{"title_ar":"موظف استقبال فندقي (شيفت مسائي)","title_en":"Hotel Receptionist (Night Shift)","slug":"hotel-receptionist-night-shift","description_ar":"فندق بوتيك في السلطان أحمد يبحث عن موظف استقبال للعمل في الوردية المسائية. المهام: استقبال النزلاء وتسهيل تسجيل الدخول والرد على الاستفسارات الهاتفية. يجب معرفة جيدة باللغة الإنجليزية والعربية.","description_en":"A boutique hotel in Sultanahmet is looking for a Night Shift Receptionist. Tasks include welcoming guests, handling check-ins/check-outs, and answering phone inquiries. Good command of English and Arabic is required.","company":"comp-tulip-hotels","category":"cat-tourism","location_ar":"السلطان أحمد، إسطنبول","location_en":"Sultanahmet, Istanbul","jobType":"full-time","salary":"22,000 - 26,000 TL","applyLink":"https://tuliphotels.example.com/careers","applyEmail":"hr@tuliphotels.example.com","language":"both","featured":false,"publishedAt":1782331377739,"status":"published"}', '{}', NULL, NULL, NULL, 1782331377739, 1782331377739);
INSERT OR REPLACE INTO documents (id, root_id, type_id, type_version, version_of_id, version_number, is_current_draft, is_published, status, parent_root_id, slug, path, title, zone, sort_order, visible, published_at, scheduled_at, expires_at, deleted_at, tenant_id, locale, translation_group_id, data, metadata, owner_id, created_by, updated_by, created_at, updated_at) VALUES ('job-english-teacher', 'job-english-teacher', 'jobs', 1, NULL, 1, 1, 1, 'published', '', 'part-time-english-tutor', NULL, 'Part-time English Tutor', NULL, 0, 1, 1782331377739, NULL, NULL, NULL, 'default', 'default', '', '{"title_ar":"مدرس لغة إنجليزية بدوام جزئي","title_en":"Part-time English Tutor","slug":"part-time-english-tutor","description_ar":"مطلوب مدرس لغة إنجليزية ناطق بها كلغة أم أو بمستواها لتدريس مجموعات صغيرة من الطلاب في باشاك شهير. العمل مسائي أو في عطلة نهاية الأسبوع. يفضل توفر شهادة CELTA أو TEFL.","description_en":"We require a native-level English teacher to tutor small groups of students at our language institute in Basaksehir. Evening or weekend sessions. CELTA/TEFL certificate is preferred.","company":"comp-ist-academy","category":"cat-education","location_ar":"باشاك شهير، إسطنبول","location_en":"Basaksehir, Istanbul","jobType":"part-time","salary":"350 TL / ساعة","applyLink":"","applyEmail":"apply@istanbulacademy.example.com","language":"en","featured":false,"publishedAt":1782331377739,"status":"published"}', '{}', NULL, NULL, NULL, 1782331377739, 1782331377739);
INSERT OR REPLACE INTO documents (id, root_id, type_id, type_version, version_of_id, version_number, is_current_draft, is_published, status, parent_root_id, slug, path, title, zone, sort_order, visible, published_at, scheduled_at, expires_at, deleted_at, tenant_id, locale, translation_group_id, data, metadata, owner_id, created_by, updated_by, created_at, updated_at) VALUES ('job-customer-rep', 'job-customer-rep', 'jobs', 1, NULL, 1, 1, 1, 'published', '', 'remote-customer-service-representative', NULL, 'Remote Customer Service Representative', NULL, 0, 1, 1782331377739, NULL, NULL, NULL, 'default', 'default', '', '{"title_ar":"ممثل خدمة عملاء كول سنتر (عمل عن بعد)","title_en":"Remote Customer Service Representative","slug":"remote-customer-service-representative","description_ar":"مطلوب موظف خدمة عملاء للعمل عن بعد لصالح متجر إلكتروني. المهام: الرد على استفسارات العملاء وحل المشكلات الفنية عبر الواتساب والإيميل. ساعات العمل مرنة ويشترط توفر إنترنت سريع وحاسوب شخصي.","description_en":"Remote customer support position for an e-commerce platform. Tasks include answering client requests and troubleshooting issues via WhatsApp and email. Flexible hours, reliable internet connection and a personal computer are required.","company":"comp-ist-tech","category":"cat-customer","location_ar":"عمل عن بعد، إسطنبول","location_en":"Remote, Istanbul","jobType":"remote","salary":"18,000 - 22,000 TL","applyLink":"https://istanbultechhub.example.com/apply","applyEmail":"careers@istanbultechhub.example.com","language":"ar","featured":false,"publishedAt":1782331377739,"status":"published"}', '{}', NULL, NULL, NULL, 1782331377739, 1782331377739);
